		*fixture.clock = accepted.UpdatedAt.Add(time.Minute)

		result, err := fixture.service.AcceptHandoffWithFollowUp(fixture.ctx, fixture.command("accepted-unlinked-legacy"))
		if err != nil {
			t.Fatalf("AcceptHandoffWithFollowUp() error = %v", err)
		}
