	return strings.TrimSpace(output.String())
}

package core

import (
	"context"
	"errors"
	"fmt"
	"strings"
)

func (s *Service) ProjectSetupReadiness(ctx context.Context, projectID string) (ProjectSetupReadiness, error) {
	projectID = strings.TrimSpace(projectID)
	if projectID == "" {
		return ProjectSetupReadiness{}, errors.Join(ErrInvalid, errors.New("project_id is required"))
	}
	project, err := s.store.GetProject(ctx, projectID)
	if err != nil {
		return ProjectSetupReadiness{}, err
	}
	workItems, err := s.store.ListWorkItems(ctx, projectID)
	if err != nil {
		return ProjectSetupReadiness{}, err
	}
	roles, err := s.store.ListRoles(ctx, projectID)
	if err != nil {
		return ProjectSetupReadiness{}, err
	}
	skills, err := s.store.ListProjectSkills(ctx, projectID)
	if err != nil {
		return ProjectSetupReadiness{}, err
	}
	memoryEntries, err := s.store.ListMemoryEntries(ctx, projectID, true)
	if err != nil {
		return ProjectSetupReadiness{}, err
	}
	memoryCandidates, err := s.store.ListMemoryCandidates(ctx, MemoryCandidateFilter{ProjectID: projectID})
	if err != nil {
		return ProjectSetupReadiness{}, err
	}

	summary := projectSetupReadinessSummary(project, workItems, roles, skills, memoryEntries, memoryCandidates)
	setupStarted := summary.EnabledContextSourceCount > 0 ||
		summary.RoleCount > 0 ||
		summary.SkillCount > 0 ||
		summary.SavedMemoryCount > 0 ||
		summary.PendingMemoryCandidateCount > 0
	return ProjectSetupReadiness{
		ProjectID:      project.ID,
		ShowOnboarding: summary.WorkItemCount == 0 && !setupStarted,
		SetupStarted:   setupStarted,
		FirstWorkReady: summary.WorkItemCount == 0 && setupStarted,
		Summary:        summary,
		PrimaryAction:  projectSetupReadinessAction(ProjectSetupActionSetupProject, project.ID, "Set up project"),
		Checks:         projectSetupReadinessChecks(project, summary),
		CreatedAt:      s.now(),
	}, nil
}

func projectSetupReadinessSummary(project Project, workItems []WorkItem, roles []Role, skills []ProjectSkill, memoryEntries []MemoryEntry, memoryCandidates []MemoryCandidate) ProjectSetupReadinessSummary {
	summary := ProjectSetupReadinessSummary{
		WorkItemCount: len(workItems),
		RoleCount:     len(roles),
		SkillCount:    len(skills),
		HasPurpose:    strings.TrimSpace(project.Description) != "",
		HasActiveRoot: projectHasActiveRoot(project),
	}
	for _, source := range project.ContextSources {
		if source.Enabled {
			summary.EnabledContextSourceCount++
		}
	}
	summary.SavedMemoryCount = len(memoryEntries)
	for _, candidate := range memoryCandidates {
		if candidate.Status == MemoryCandidatePending {
			summary.PendingMemoryCandidateCount++
		}
	}
	return summary
}

func projectSetupReadinessChecks(project Project, summary ProjectSetupReadinessSummary) []ProjectSetupReadinessCheck {
	projectID := project.ID
	hasContext := summary.EnabledContextSourceCount > 0 || summary.SkillCount > 0 || summary.SavedMemoryCount > 0 || summary.PendingMemoryCandidateCount > 0
	return []ProjectSetupReadinessCheck{
		projectSetupCheck("purpose", "Project purpose", strings.TrimSpace(project.Description), summary.HasPurpose, false, projectSetupReadinessAction(ProjectSetupActionUpdateProject, projectID, "Add purpose"), "Add a short purpose."),
		projectSetupWorkspaceCheck(project),
		projectSetupCheck("sources_memory", "Sources and memory", projectSetupGuidanceDetail(summary, project), hasContext, false, projectSetupReadinessAction(ProjectSetupActionManageContext, projectID, "Add context"), ""),
		projectSetupCheck("roles", "Roles", projectSetupRoleDetail(summary), summary.RoleCount > 0, false, projectSetupReadinessAction(ProjectSetupActionManageRoles, projectID, "Create role"), ""),
		projectSetupCheck("first_work_item", "First work item", projectSetupFirstWorkDetail(summary), summary.WorkItemCount > 0, false, projectSetupReadinessAction(ProjectSetupActionCreateWorkItem, projectID, "Create work item"), ""),
	}
}

func projectSetupCheck(id, label, detail string, done, optional bool, action ProjectSetupReadinessAction, fallbackDetail string) ProjectSetupReadinessCheck {
	status := ProjectSetupStatusTodo
	if done {
		status = ProjectSetupStatusReady
	} else if optional {
		status = ProjectSetupStatusOptional
	}
	check := ProjectSetupReadinessCheck{
		ID:       id,
		Label:    label,
		Detail:   strings.TrimSpace(detail),
		Status:   status,
		Optional: optional,
	}
	if check.Detail == "" {
		check.Detail = fallbackDetail
	}
	if !done && !optional {
		check.Action = &action
	}
	return check
}

func projectSetupWorkspaceCheck(project Project) ProjectSetupReadinessCheck {
	if root, ok := projectActiveRoot(project); ok {
		return ProjectSetupReadinessCheck{
			ID:       "workspace_source",
			Label:    "Workspace source",
			Detail:   root.Path,
			Status:   ProjectSetupStatusReady,
			Optional: true,
		}
	}
	return ProjectSetupReadinessCheck{
		ID:       "workspace_source",
		Label:    "Workspace source",
		Detail:   "Optional; attach files when this project needs them.",
		Status:   ProjectSetupStatusOptional,
		Optional: true,
	}
}

func projectActiveRoot(project Project) (Root, bool) {
	for _, root := range project.Roots {
		if root.Active && strings.TrimSpace(root.Path) != "" {
			return root, true
		}
	}
	return Root{}, false
}

func projectHasActiveRoot(project Project) bool {
	_, ok := projectActiveRoot(project)
	return ok
}

func projectSetupGuidanceDetail(summary ProjectSetupReadinessSummary, project Project) string {
	parts := make([]string, 0, 4)
	if summary.EnabledContextSourceCount > 0 {
		parts = append(parts, projectSetupCountLabel(summary.EnabledContextSourceCount, "source"))
	}
	if summary.SkillCount > 0 {
		parts = append(parts, projectSetupCountLabel(summary.SkillCount, "skill"))
	}
	if summary.SavedMemoryCount > 0 {
		parts = append(parts, projectSetupCountLabel(summary.SavedMemoryCount, "memory"))
	}
	if summary.PendingMemoryCandidateCount > 0 {
		parts = append(parts, projectSetupCountLabel(summary.PendingMemoryCandidateCount, "candidate"))
	}
	if len(parts) > 0 {
		return strings.Join(parts, " · ")
	}
	if projectHasActiveRoot(project) {
		return "Discover workspace guidance or add project memory before assigning work."
	}
	return "Add context sources or memory when useful for this project."
}

func projectSetupRoleDetail(summary ProjectSetupReadinessSummary) string {
	if summary.RoleCount > 0 {
		return projectSetupCountLabel(summary.RoleCount, "role")
	}
	return "Create responsibilities such as operator, implementer, reviewer, researcher, or designer."
}

func projectSetupFirstWorkDetail(summary ProjectSetupReadinessSummary) string {
	if summary.WorkItemCount > 0 {
		return projectSetupCountLabel(summary.WorkItemCount, "work item")
	}
	return "Create the first reviewable task after setup."
}

func projectSetupCountLabel(count int, singular string) string {
	if count == 1 {
		return "1 " + singular
	}
	plural := singular + "s"
	if strings.HasSuffix(singular, "y") {
		plural = strings.TrimSuffix(singular, "y") + "ies"
	}
	return fmt.Sprintf("%d %s", count, plural)
}

func projectSetupReadinessAction(kind, projectID, label string) ProjectSetupReadinessAction {
	return ProjectSetupReadinessAction{
		Kind:      kind,
		ProjectID: projectID,
		Label:     label,
	}
}

package mcp

import "encoding/json"

const DeclaredProtocolVersion = "2025-11-25"

type Request struct {
	JSONRPC string           `json:"jsonrpc"`
	ID      *json.RawMessage `json:"id,omitempty"`
	Method  string           `json:"method"`
	Params  json.RawMessage  `json:"params,omitempty"`
}

func (r Request) IsNotification() bool { return r.ID == nil }

type Response struct {
	JSONRPC string           `json:"jsonrpc"`
	ID      *json.RawMessage `json:"id"`
	Result  json.RawMessage  `json:"result,omitempty"`
	Error   *RPCError        `json:"error,omitempty"`
}

type RPCError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

func (e *RPCError) Error() string { return e.Message }

const (
	ErrCodeParseError     = -32700
	ErrCodeInvalidRequest = -32600
	ErrCodeMethodNotFound = -32601
	ErrCodeInvalidParams  = -32602
	ErrCodeInternalError  = -32603
)

func NewError(code int, message string) *RPCError {
	return &RPCError{Code: code, Message: message}
}

type InitializeParams struct {
	ProtocolVersion string             `json:"protocolVersion"`
	Capabilities    ClientCapabilities `json:"capabilities,omitempty"`
	ClientInfo      ClientInfo         `json:"clientInfo,omitempty"`
}

// ClientCapabilities carries the capability declarations a client sends during
// initialize. Extensions mirrors the server-side extension map so a host can
// negotiate optional protocol extensions; Cairnline parses the client's
// declarations and declares its own via DeclareExtension (e.g.
// io.modelcontextprotocol/ui once an MCP Apps view is registered).
type ClientCapabilities struct {
	Extensions map[string]json.RawMessage `json:"extensions,omitempty"`
}

type ClientInfo struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type InitializeResult struct {
	ProtocolVersion string             `json:"protocolVersion"`
	Capabilities    ServerCapabilities `json:"capabilities"`
	ServerInfo      ServerInfo         `json:"serverInfo"`
}

type ServerCapabilities struct {
	Tools      *ToolsCapability           `json:"tools,omitempty"`
	Resources  *ResourcesCapability       `json:"resources,omitempty"`
	Extensions map[string]json.RawMessage `json:"extensions,omitempty"`
}

type ToolsCapability struct {
	ListChanged bool `json:"listChanged,omitempty"`
}

type ResourcesCapability struct {
	Subscribe   bool `json:"subscribe,omitempty"`
	ListChanged bool `json:"listChanged,omitempty"`
}

type ServerInfo struct {
	Name        string `json:"name"`
	Version     string `json:"version"`
	Description string `json:"description,omitempty"`
}

type Tool struct {
	Name         string           `json:"name"`
	Title        string           `json:"title,omitempty"`
	Description  string           `json:"description,omitempty"`
	InputSchema  json.RawMessage  `json:"inputSchema"`
	OutputSchema json.RawMessage  `json:"outputSchema,omitempty"`
	Annotations  *ToolAnnotations `json:"annotations,omitempty"`
	Meta         map[string]any   `json:"_meta,omitempty"`
}

type ToolAnnotations struct {
	ReadOnlyHint    *bool `json:"readOnlyHint,omitempty"`
	DestructiveHint *bool `json:"destructiveHint,omitempty"`
	IdempotentHint  *bool `json:"idempotentHint,omitempty"`
}

func BoolPtr(v bool) *bool { return &v }

type ListToolsResult struct {
	Tools []Tool `json:"tools"`
}

type Resource struct {
	URI         string         `json:"uri"`
	Name        string         `json:"name"`
	Title       string         `json:"title,omitempty"`
	Description string         `json:"description,omitempty"`
	MimeType    string         `json:"mimeType,omitempty"`
	Meta        map[string]any `json:"_meta,omitempty"`
}

type ResourceTemplate struct {
	URITemplate string `json:"uriTemplate"`
	Name        string `json:"name"`
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	MimeType    string `json:"mimeType,omitempty"`
}

type ListResourcesResult struct {
	Resources []Resource `json:"resources"`
}

type ListResourceTemplatesResult struct {
	ResourceTemplates []ResourceTemplate `json:"resourceTemplates"`
}

type ReadResourceParams struct {
	URI string `json:"uri"`
}

type ReadResourceResult struct {
	Contents []ResourceContent `json:"contents"`
}

// ResourceContent is the body of a resource. Text carries UTF-8 payloads and
// Blob carries base64-encoded binary payloads; the two are mutually exclusive
// per the MCP spec. ResourceContent also backs embedded-resource tool results
// (see Content.Resource).
type ResourceContent struct {
	URI      string         `json:"uri"`
	MimeType string         `json:"mimeType,omitempty"`
	Text     string         `json:"text,omitempty"`
	Blob     string         `json:"blob,omitempty"`
	Meta     map[string]any `json:"_meta,omitempty"`
}

type CallToolParams struct {
	Name      string          `json:"name"`
	Arguments json.RawMessage `json:"arguments,omitempty"`
}

type CallToolResult struct {
	Content           []Content      `json:"content"`
	StructuredContent any            `json:"structuredContent,omitempty"`
	IsError           bool           `json:"isError,omitempty"`
	Meta              map[string]any `json:"_meta,omitempty"`
}

// Content is a single tool-result content block. Type selects the variant:
// "text" uses Text; "resource" embeds a ResourceContent (text or blob) via
// Resource.
type Content struct {
	Type     string           `json:"type"`
	Text     string           `json:"text,omitempty"`
	Resource *ResourceContent `json:"resource,omitempty"`
}

func TextContent(text string) []Content {
	return []Content{{Type: "text", Text: text}}
}

// ToolErrorPayload is the StructuredContent carried on a failed tool call. It
// gives hosts a machine-readable error alongside the unchanged human-readable
// Content, so a client can branch on Error.Code without parsing prose.
type ToolErrorPayload struct {
	Error ToolErrorDetail `json:"error"`
}

// ToolErrorDetail names the failure class (see the cairnline ErrorCode*
// contract) and echoes the underlying error message.
type ToolErrorDetail struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// EmbeddedResource returns a content block that embeds a resource payload in a
// tool result. The resource may carry either Text or Blob content.
func EmbeddedResource(resource ResourceContent) Content {
	return Content{Type: "resource", Resource: &resource}
}

package mcp

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"sync"

	"github.com/hecatehq/cairnline/internal/core"
)

type ToolHandler func(context.Context, json.RawMessage) (CallToolResult, error)
type ResourceProvider func(context.Context) ([]Resource, error)
type ResourceReader func(context.Context, string) (ReadResourceResult, bool, error)

type Server struct {
	info              ServerInfo
	tools             map[string]registeredTool
	resourceProviders []ResourceProvider
	resourceReaders   []ResourceReader
	resourceTemplates []ResourceTemplate
	extensions        map[string]json.RawMessage

	writeMu sync.Mutex
}

type registeredTool struct {
	descriptor Tool
	handler    ToolHandler
}

func NewServer(name, version, description string) *Server {
	return &Server{
		info: ServerInfo{
			Name:        name,
			Version:     version,
			Description: description,
		},
		tools: make(map[string]registeredTool),
	}
}

func (s *Server) RegisterTool(tool Tool, handler ToolHandler) {
	s.tools[tool.Name] = registeredTool{descriptor: tool, handler: handler}
}

func (s *Server) RegisterResourceProvider(provider ResourceProvider, reader ResourceReader) {
	s.resourceProviders = append(s.resourceProviders, provider)
	s.resourceReaders = append(s.resourceReaders, reader)
}

func (s *Server) RegisterResourceTemplates(templates []ResourceTemplate) {
	s.resourceTemplates = append(s.resourceTemplates, templates...)
}

// DeclareExtension advertises a protocol extension in the server's initialize
// capabilities under its extension id (for example "io.modelcontextprotocol/ui").
// config is the extension's capability object, passed through verbatim; pass nil
// to declare an extension with no configuration. Declaring an extension lets a
// host negotiate it during initialize; Cairnline ships with none declared.
func (s *Server) DeclareExtension(id string, config json.RawMessage) {
	if s.extensions == nil {
		s.extensions = make(map[string]json.RawMessage)
	}
	if config == nil {
		config = json.RawMessage("{}")
	}
	s.extensions[id] = config
}

func (s *Server) Serve(ctx context.Context, in io.Reader, out io.Writer) error {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)

	go func() {
		<-ctx.Done()
		if closer, ok := in.(io.Closer); ok {
			_ = closer.Close()
		}
	}()

	var wg sync.WaitGroup
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		msg := make([]byte, len(line))
		copy(msg, line)
		wg.Add(1)
		go func() {
			defer wg.Done()
			if response, ok := s.HandleMessage(ctx, msg); ok {
				s.write(out, response)
			}
		}()
	}
	wg.Wait()

	if err := scanner.Err(); err != nil && !errors.Is(err, io.EOF) {
		return fmt.Errorf("mcp scanner: %w", err)
	}
	return nil
}

// HandleMessage processes a single JSON-RPC message and returns the encoded
// response. The boolean is false for notifications, which produce no response.
// Embedding hosts that mount Cairnline's MCP surface on their own transport call
// HandleMessage per inbound message instead of Serve, which owns the stdio loop.
func (s *Server) HandleMessage(ctx context.Context, raw []byte) ([]byte, bool) {
	var req Request
	if err := json.Unmarshal(raw, &req); err != nil {
		return encodeResponse(errorResponse(nil, NewError(ErrCodeParseError, "parse error: "+err.Error()))), true
	}
	if req.JSONRPC != "2.0" {
		return encodeResponse(errorResponse(req.ID, NewError(ErrCodeInvalidRequest, "jsonrpc must be \"2.0\""))), true
	}
	result, rpcErr := s.dispatch(ctx, req)
	if req.IsNotification() {
		return nil, false
	}
	if rpcErr != nil {
		return encodeResponse(errorResponse(req.ID, rpcErr)), true
	}
	return encodeResponse(successResponse(req.ID, result)), true
}

func (s *Server) dispatch(ctx context.Context, req Request) (any, *RPCError) {
	switch req.Method {
	case "initialize":
		return s.handleInitialize(req.Params)
	case "notifications/initialized":
		return struct{}{}, nil
	case "tools/list":
		return s.handleListTools(), nil
	case "tools/call":
		return s.handleCallTool(ctx, req.Params)
	case "resources/list":
		return s.handleListResources(ctx)
	case "resources/templates/list":
		return s.handleListResourceTemplates(), nil
	case "resources/read":
		return s.handleReadResource(ctx, req.Params)
	case "ping":
		return struct{}{}, nil
	default:
		return nil, NewError(ErrCodeMethodNotFound, "method not found: "+req.Method)
	}
}

func (s *Server) handleInitialize(raw json.RawMessage) (any, *RPCError) {
	var params InitializeParams
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, NewError(ErrCodeInvalidParams, "invalid initialize params: "+err.Error())
		}
	}
	// params.Capabilities carries the client's extension declarations; parsing it
	// keeps extension negotiation open. Cairnline's own declared extensions (e.g.
	// io.modelcontextprotocol/ui when an MCP Apps view is registered) are returned
	// in the initialize result via capabilities().
	return InitializeResult{
		ProtocolVersion: DeclaredProtocolVersion,
		Capabilities:    s.capabilities(),
		ServerInfo:      s.info,
	}, nil
}

func (s *Server) capabilities() ServerCapabilities {
	capabilities := ServerCapabilities{Tools: &ToolsCapability{}}
	if len(s.resourceProviders) > 0 || len(s.resourceTemplates) > 0 {
		capabilities.Resources = &ResourcesCapability{}
	}
	if len(s.extensions) > 0 {
		extensions := make(map[string]json.RawMessage, len(s.extensions))
		for id, config := range s.extensions {
			extensions[id] = config
		}
		capabilities.Extensions = extensions
	}
	return capabilities
}

func (s *Server) handleListTools() ListToolsResult {
	tools := make([]Tool, 0, len(s.tools))
	for _, item := range s.tools {
		tools = append(tools, item.descriptor)
	}
	return ListToolsResult{Tools: tools}
}

func (s *Server) handleListResources(ctx context.Context) (any, *RPCError) {
	resources := make([]Resource, 0)
	for _, provider := range s.resourceProviders {
		items, err := provider(ctx)
		if err != nil {
			return nil, NewError(ErrCodeInternalError, "list resources: "+err.Error())
		}
		resources = append(resources, items...)
	}
	return ListResourcesResult{Resources: resources}, nil
}

func (s *Server) handleListResourceTemplates() ListResourceTemplatesResult {
	templates := make([]ResourceTemplate, len(s.resourceTemplates))
	copy(templates, s.resourceTemplates)
	return ListResourceTemplatesResult{ResourceTemplates: templates}
}

func (s *Server) handleReadResource(ctx context.Context, raw json.RawMessage) (any, *RPCError) {
	var params ReadResourceParams
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, NewError(ErrCodeInvalidParams, "invalid resource read params: "+err.Error())
		}
	}
	if params.URI == "" {
		return nil, NewError(ErrCodeInvalidParams, "resource uri is required")
	}
	for _, reader := range s.resourceReaders {
		result, ok, err := reader(ctx, params.URI)
		if err != nil {
			return nil, NewError(ErrCodeInternalError, "read resource: "+err.Error())
		}
		if ok {
			return result, nil
		}
	}
	return nil, NewError(ErrCodeInvalidParams, "unknown resource: "+params.URI)
}

func (s *Server) handleCallTool(ctx context.Context, raw json.RawMessage) (any, *RPCError) {
	var params CallToolParams
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &params); err != nil {
			return nil, NewError(ErrCodeInvalidParams, "invalid tool call params: "+err.Error())
		}
	}
	tool, ok := s.tools[params.Name]
	if !ok {
		return nil, NewError(ErrCodeInvalidParams, "unknown tool: "+params.Name)
	}
	result, err := tool.handler(ctx, params.Arguments)
	if err != nil {
		// Single tool-error path for every registered handler: keep the human
		// prose in Content untouched and attach a machine-readable error code
		// so hosts can classify the failure without parsing the message.
		return CallToolResult{
			Content: TextContent(err.Error()),
			StructuredContent: ToolErrorPayload{Error: ToolErrorDetail{
				Code:    core.ClassifyErrorCode(err),
				Message: err.Error(),
			}},
			IsError: true,
		}, nil
	}
	return result, nil
}

func (s *Server) write(out io.Writer, payload []byte) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	_, _ = out.Write(append(payload, '\n'))
}

func encodeResponse(response Response) []byte {
	raw, err := json.Marshal(response)
	if err != nil {
		raw, _ = json.Marshal(errorResponse(response.ID, NewError(ErrCodeInternalError, "marshal response: "+err.Error())))
	}
	return raw
}

func successResponse(id *json.RawMessage, result any) Response {
	raw, err := json.Marshal(result)
	if err != nil {
		return errorResponse(id, NewError(ErrCodeInternalError, "marshal result: "+err.Error()))
	}
	return Response{JSONRPC: "2.0", ID: id, Result: raw}
}

func errorResponse(id *json.RawMessage, rpcErr *RPCError) Response {
	return Response{JSONRPC: "2.0", ID: id, Error: rpcErr}
}

package cairnline_test

import (
	"errors"
	"fmt"
	"testing"

	"github.com/hecatehq/cairnline"
)

func TestClassifyErrorCode(t *testing.T) {
	tests := []struct {
		name string
		err  error
		want string
	}{
		{name: "nil error", err: nil, want: ""},
		{name: "not found", err: cairnline.ErrNotFound, want: cairnline.ErrorCodeNotFound},
		{name: "wrapped not found", err: fmt.Errorf("root: %w", cairnline.ErrNotFound), want: cairnline.ErrorCodeNotFound},
		{name: "duplicate is already_exists", err: errors.Join(cairnline.ErrDuplicate, errors.New("dup")), want: cairnline.ErrorCodeAlreadyExists},
		{name: "conflict", err: errors.Join(cairnline.ErrConflict, errors.New("race")), want: cairnline.ErrorCodeConflict},
		{name: "invalid", err: errors.Join(cairnline.ErrInvalid, errors.New("bad input")), want: cairnline.ErrorCodeInvalid},
		{name: "unclassified is internal", err: errors.New("boom"), want: cairnline.ErrorCodeInternal},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := cairnline.ClassifyErrorCode(tc.err); got != tc.want {
				t.Fatalf("ClassifyErrorCode(%v) = %q, want %q", tc.err, got, tc.want)
			}
		})
	}
}

